<script lang="ts">import{gradientPickerStopClassName}from'@fex-design/styles/color-picker';import{cn}from'@fex/utils';import type{HTMLButtonAttributes}from'svelte/elements';import{useGradientPicker}from'./context';interface Props extends HTMLButtonAttributes{id:string}let{id,class:className,...rest}:Props=$props();const picker=useGradientPicker(),snapshot=$derived(picker.snapshot()),stop=$derived(snapshot.value.stops.find(item=>item.id===id))</script>{#if stop}<button {...rest} type="button" disabled={snapshot.disabled} data-selected={snapshot.selectedStopId===id||undefined} class={cn(gradientPickerStopClassName,className)} style:left={`clamp(6px, ${stop.position*100}%, calc(100% - 6px))`} style:--gradient-stop-color={stop.color.toString('rgb')} onpointerdown={(event)=>{event.currentTarget.setPointerCapture(event.pointerId);picker.controller.selectStop(id);picker.controller.beginInteraction('stop-move')}} onpointermove={(event)=>{if(!event.currentTarget.hasPointerCapture(event.pointerId))return;const rect=event.currentTarget.parentElement!.getBoundingClientRect();picker.controller.moveStop(id,(event.clientX-rect.left)/rect.width)}} onpointerup={(event)=>{if(event.currentTarget.hasPointerCapture(event.pointerId)){event.currentTarget.releasePointerCapture(event.pointerId);picker.controller.completeInteraction()}}}/>{/if}
